import { supabase } from '../../../lib/supabase';
import { personalWalletService } from '../../../services/personalWallet.service';

export type WalletSnapshot = Awaited<ReturnType<typeof personalWalletService.load>>;

// Reuse simultaneous requests generated by route changes and realtime events.
// The default account RPC is only required once per loaded browser session.
let pending: Promise<WalletSnapshot> | null = null;
let initialization: Promise<void> | null = null;

function ensureWalletInitialized(): Promise<void> {
  if (!initialization) {
    initialization = personalWalletService.ensureDefaultCashAccount().catch(error => {
      initialization = null; // A failed initialization must be retriable.
      throw error;
    });
  }
  return initialization;
}

export const walletRepository = {
  load(): Promise<WalletSnapshot> {
    if (pending) return pending;
    const work = (async () => {
      await ensureWalletInitialized();
      return personalWalletService.load();
    })();
    pending = work;
    void work.finally(() => { if (pending === work) pending = null; }).catch(() => {});
    return work;
  },
  async getAccess(userId: string) {
    const { data, error } = await supabase
      .from('user_modulos')
      .select('ativo,configuracoes')
      .eq('user_id', userId)
      .eq('modulo_chave', 'carteira')
      .maybeSingle();
    if (error) throw new Error(error.message);
    return data ? { active: Boolean(data.ativo), settings: data.configuracoes ?? {} } : { active: false, settings: {} };
  },
};
